import { render, screen, fireEvent } from '@testing-library/react-native';import AchievementsScreen from '../achievements_screen';import AchievementService from '../../services/achievement_service';jest.mock('../../services/achievement_service');describe('AchievementsScreen', () => {  let mockAchievements;  beforeEach(() => {    mockAchievements = [      { id: '1', name: 'Achievement 1', description: 'Description 1', claimed: false },      { id: '2', name: 'Achievement 2', description: 'Description 2', claimed: true },    ];    AchievementService.mockImplementation(() => ({      syncWithServer: jest.fn().mockResolvedValue(mockAchievements),      unlockAchievement: jest.fn().mockResolvedValue(true),    }));  });  it('renders loading indicator initially', () => {    render(<AchievementsScreen />);    expect(screen.getByTestId('loading-indicator')).toBeTruthy();  });  it('renders achievements list after loading', async () => {    render(<AchievementsScreen />);    await screen.findByText('Achievement 1');    expect(screen.getByText('Achievement 1')).toBeTruthy();    expect(screen.getByText('Description 1')).toBeTruthy();    expect(screen.getByText('Achievement 2')).toBeTruthy();    expect(screen.getByText('Description 2')).toBeTruthy();  });  it('calls unlockAchievement when claim button is pressed', async () => {    const mockUnlock = jest.fn().mockResolvedValue(true);    AchievementService.mockImplementation(() => ({      syncWithServer: jest.fn().mockResolvedValue(mockAchievements),      unlockAchievement: mockUnlock,    }));    render(<AchievementsScreen />);    await screen.findByText('Achievement 1');    fireEvent.press(screen.getByText('Claim'));    expect(mockUnlock).toHaveBeenCalledWith('user123', '1');  });  it('handles search achievements', async () => {    render(<AchievementsScreen />);    await screen.findByText('Achievement 1');    const searchInput = screen.getByPlaceholderText('Search achievements');    fireEvent.changeText(searchInput, '1');    expect(screen.getByText('Achievement 1')).toBeTruthy();    expect(screen.queryByText('Achievement 2')).toBeNull();  });});